&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.27.0&lt;/Version&gt;
    &lt;Build&gt;5.27.144&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;917&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (
    SELECT
        [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare
),
ExceptiiLichidate AS (
    SELECT
        a.Id,
        a.Marca,
        a.Nume,
        a.CodSucursala,
        p.ZileLucratoare,
        ISNULL(co.ZileCOLuna, 0) AS ZileCO,
        ISNULL(cm.ZileCMLuna, 0) AS ZileCM,

        CASE 
            WHEN (ISNULL(co.ZileCOLuna,0) + ISNULL(cm.ZileCMLuna,0) &amp;gt;= p.ZileLucratoare) 
                 AND ISNULL(co.ZileCOLuna,0) &amp;gt; 0 
                 AND ISNULL(cm.ZileCMLuna,0) &amp;gt; 0 
            THEN &#39;CO_CM&#39; 

            WHEN ISNULL(co.ZileCOLuna,0) &amp;gt;= p.ZileLucratoare 
                 AND ISNULL(cm.ZileCMLuna,0)=0 
            THEN &#39;CO&#39; 

            WHEN ISNULL(cm.ZileCMLuna,0) &amp;gt;= p.ZileLucratoare 
                 AND  ISNULL(co.ZileCOLuna,0)= 0 
            THEN &#39;CM&#39; 
        END AS TipExceptie, 

        CASE 
            WHEN ISNULL(co.ZileCOLuna,0) + ISNULL(cm.ZileCMLuna,0) &amp;gt;= p.ZileLucratoare 
                 AND ISNULL(co.ZileCOLuna,0) &amp;gt; 0 
                 AND ISNULL(cm.ZileCMLuna,0)&amp;gt;0 
            THEN &#39;CO + CM ≥ Zile lucrătoare&#39;

            WHEN ISNULL(co.ZileCOLuna,0) &amp;gt;= p.ZileLucratoare 
                 AND ISNULL(cm.ZileCMLuna,0) = 0 
            THEN &#39;Concediu de odihnă integral&#39;

            WHEN ISNULL(cm.ZileCMLuna,0) &amp;gt;= p.ZileLucratoare 
                 AND ISNULL(co.ZileCOLuna,0) = 0 
            THEN &#39;Concediu medical integral&#39; 
        END AS Detalii

    FROM app.Salariat a
    CROSS JOIN Parametri p

    OUTER APPLY (
        SELECT SUM(
            CASE WHEN c.Interval1DatadeInceput IS NOT NULL AND MONTH(c.Interval1DatadeInceput) = @Luna AND YEAR (c.Interval1DatadeInceput) = @Anul THEN ISNULL(c.NrZileCO1, 0) ELSE 0 END + 
            CASE WHEN c.Interval2DatadeInceput IS NOT NULL AND MONTH(c.Interval2DatadeInceput) = @Luna AND YEAR (c.Interval2DatadeInceput) = @Anul THEN ISNULL(c.NrZileCO2, 0) ELSE 0 END + 
            CASE WHEN c.Interval3DatadeInceput IS NOT NULL AND MONTH(c.Interval3DatadeInceput) = @Luna AND YEAR (c.Interval3DatadeInceput) = @Anul THEN ISNULL(c.NrZileCO3, 0) ELSE 0 END
        ) AS ZileCOLuna
        FROM app.ConcediudeOdihna c
        WHERE c.Marca = a.Marca 
          AND c.CodSucursala = a.CodSucursala 
          AND c.CodSucursala = @CodSucursala
    ) co

    OUTER APPLY (
        SELECT SUM(m.TotZileLucratoare) AS ZileCMLuna
        FROM app.ConcediuMedical m
        WHERE m.Marca = a.Marca 
          AND m.CodSucursala = @CodSucursala 
          AND m.AnulDePlata = @Anul 
          AND m.LunaDePlata = @Luna
    ) cm

    CROSS APPLY (
        SELECT CASE 
            WHEN p.ZileLucratoare - ISNULL(co.ZileCOLuna, 0) - ISNULL(cm.ZileCMLuna, 0) &amp;lt;= 0 THEN 0 
            ELSE p.ZileLucratoare - ISNULL(co.ZileCOLuna, 0) - ISNULL(cm.ZileCMLuna, 0) 
        END AS ZileLucrate
    ) zl

    WHERE zl.ZileLucrate = 0
      AND a.Anul = @Anul
      AND a.Luna = @Luna
      AND a.CodSucursala = @CodSucursala
)

SELECT 
    ex.Id,
    ex.Marca,
    ex.Nume,
    ex.TipExceptie AS MotivLipsaLunara,
    ex.Detalii AS ExplicatieLipsa,
    COUNT(ag.Id) AS NumarPrestatiiInregistrate,
    ISNULL(SUM(ag.Suma), 0) AS TotalSumaPrestatiiInvalide
FROM ExceptiiLichidate ex
INNER JOIN app.Agent ag 
    ON ex.Marca = ag.Marca
   AND ex.CodSucursala = ag.CodSucursala
   AND ag.Anul = @Anul
   AND ag.Luna = @Luna
GROUP BY 
    ex.Id,
    ex.Marca,
    ex.Nume,
    ex.TipExceptie,
    ex.Detalii
HAVING 
    SUM(ag.Suma) &amp;gt; 0 OR COUNT(ag.Id) &amp;gt; 0&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Marca&quot;,&quot;Name&quot;:&quot;Marca&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Nume&quot;,&quot;Name&quot;:&quot;Nume&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;MotivLipsaLunara&quot;,&quot;Name&quot;:&quot;MotivLipsaLunara&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ExplicatieLipsa&quot;,&quot;Name&quot;:&quot;ExplicatieLipsa&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;NumarPrestatiiInregistrate&quot;,&quot;Name&quot;:&quot;NumarPrestatiiInregistrate&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalSumaPrestatiiInvalide&quot;,&quot;Name&quot;:&quot;TotalSumaPrestatiiInvalide&quot;,&quot;TypeStr&quot;:&quot;System.Decimal, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
    &lt;ShowTitle&gt;True&lt;/ShowTitle&gt;
    &lt;NoDataMessage&gt;No Data&lt;/NoDataMessage&gt;
    &lt;AditionalHtmlHeader /&gt;
    &lt;OnInitJs /&gt;
    &lt;OnRefreshJs /&gt;
    &lt;EnableEmbed&gt;False&lt;/EnableEmbed&gt;
    &lt;ShowCondition /&gt;
    &lt;SearchPlaceholder&gt;Search&lt;/SearchPlaceholder&gt;
    &lt;SearchDelayTime&gt;300&lt;/SearchDelayTime&gt;
    &lt;TableHeight /&gt;
    &lt;PagerStyle&gt;TouchFriendly&lt;/PagerStyle&gt;
    &lt;DisplayMode&gt;Always&lt;/DisplayMode&gt;
    &lt;PopupWidth /&gt;
    &lt;WidthCoordinate&gt;px&lt;/WidthCoordinate&gt;
    &lt;PopupName /&gt;
    &lt;PageSizes&gt;[12,24,48]&lt;/PageSizes&gt;
    &lt;DefaultPageSize&gt;12&lt;/DefaultPageSize&gt;
    &lt;IsDebug&gt;False&lt;/IsDebug&gt;
    &lt;SearchEnabled&gt;True&lt;/SearchEnabled&gt;
    &lt;ExactSearch&gt;False&lt;/ExactSearch&gt;
    &lt;HideEmptyGrid&gt;True&lt;/HideEmptyGrid&gt;
    &lt;LoadOnSearch&gt;False&lt;/LoadOnSearch&gt;
    &lt;HideTableHead&gt;False&lt;/HideTableHead&gt;
    &lt;EnableStickyHead&gt;False&lt;/EnableStickyHead&gt;
    &lt;ItemButtonPosition&gt;Right&lt;/ItemButtonPosition&gt;
    &lt;ItemButtonPositionInColumn&gt;Right&lt;/ItemButtonPositionInColumn&gt;
    &lt;ItemButtonGroupingOptions&gt;HorizontalAlign&lt;/ItemButtonGroupingOptions&gt;
    &lt;FiltersEnabled&gt;True&lt;/FiltersEnabled&gt;
    &lt;ShowFilters&gt;False&lt;/ShowFilters&gt;
    &lt;SyncUrl&gt;False&lt;/SyncUrl&gt;
    &lt;IncludeBootstrapJS&gt;True&lt;/IncludeBootstrapJS&gt;
    &lt;IncludeBootstrapCSS&gt;True&lt;/IncludeBootstrapCSS&gt;
    &lt;IncludeFontAwesome&gt;True&lt;/IncludeFontAwesome&gt;
    &lt;AngularnoConflict&gt;True&lt;/AngularnoConflict&gt;
    &lt;SelectAllPosition&gt;None&lt;/SelectAllPosition&gt;
    &lt;SearchPosition&gt;top&lt;/SearchPosition&gt;
    &lt;RootCSSClasses /&gt;
    &lt;ModalRefresh&gt;False&lt;/ModalRefresh&gt;
    &lt;ShowLoading&gt;True&lt;/ShowLoading&gt;
    &lt;TabsProLoading&gt;True&lt;/TabsProLoading&gt;
    &lt;EnableGridSelect&gt;True&lt;/EnableGridSelect&gt;
    &lt;DataSourceAutoRefreshInterval&gt;1&lt;/DataSourceAutoRefreshInterval&gt;
    &lt;DataSourceRefreshType&gt;manual&lt;/DataSourceRefreshType&gt;
    &lt;DateFormat&gt;m/d/yy&lt;/DateFormat&gt;
    &lt;ItemButtonGroups&gt;[]&lt;/ItemButtonGroups&gt;
    &lt;GridButtonGroups&gt;[]&lt;/GridButtonGroups&gt;
    &lt;ItemButtons&gt;[]&lt;/ItemButtons&gt;
    &lt;GridButtons&gt;[]&lt;/GridButtons&gt;
    &lt;PortalHomeUrl&gt;/Portals/0/&lt;/PortalHomeUrl&gt;
    &lt;TooltipContent /&gt;
