    &lt;TooltipIcon&gt;glyphicon-info-sign&lt;/TooltipIcon&gt;
    &lt;TooltipIconPosition&gt;right&lt;/TooltipIconPosition&gt;
    &lt;TooltipInEdit&gt;right&lt;/TooltipInEdit&gt;
    &lt;TooltipEnabled&gt;false&lt;/TooltipEnabled&gt;
    &lt;TooltipOrientation /&gt;
    &lt;TooltipTitle /&gt;
    &lt;TooltipHeight&gt;0&lt;/TooltipHeight&gt;
    &lt;TooltipWidth&gt;0&lt;/TooltipWidth&gt;
    &lt;DefaultDesktopView /&gt;
    &lt;DefaultMobileView /&gt;
    &lt;RefreshOnTabChange&gt;False&lt;/RefreshOnTabChange&gt;
    &lt;UseDragAndDropActions&gt;False&lt;/UseDragAndDropActions&gt;
    &lt;DragAndDropActions&gt;[]&lt;/DragAndDropActions&gt;
    &lt;InitLoadFromTabsPro&gt;False&lt;/InitLoadFromTabsPro&gt;
    &lt;LockIntoEditMode&gt;False&lt;/LockIntoEditMode&gt;
    &lt;LockInEditForEachRowActions&gt;[]&lt;/LockInEditForEachRowActions&gt;
    &lt;LockInEditFinalActions&gt;[]&lt;/LockInEditFinalActions&gt;
    &lt;Template /&gt;
    &lt;MobileTemplate /&gt;
    &lt;SwitchingTemplates&gt;False&lt;/SwitchingTemplates&gt;
    &lt;TemplateConfig&gt;{}&lt;/TemplateConfig&gt;
    &lt;Views&gt;[{&quot;Definition&quot;:{&quot;Id&quot;:&quot;Calendar&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Calendar&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Renders data in a calendar based on a date field.&quot;},&quot;FaIcon&quot;:&quot;far fa-calendar-alt&quot;,&quot;TypeStr&quot;:&quot;PlantAnApp.Listing.ViewProviders.CalendarViewProvider, DnnSharp.ActionGrid.Core&quot;,&quot;Settings&quot;:{&quot;showWhenNoData&quot;:true},&quot;Parameters&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;EventCssClasses&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Event Css Classes&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;The custom Css classes for each item&quot;},&quot;Placeholder&quot;:null,&quot;DefaultValue&quot;:null,&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;SupportsExpressions&quot;:true},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]}]},&quot;Id&quot;:890,&quot;ListingModuleId&quot;:917,&quot;ViewName&quot;:&quot;Calendar&quot;,&quot;ViewTitle&quot;:&quot;Calendar&quot;,&quot;RendersTopButtons&quot;:false,&quot;RendersBottomButtons&quot;:false,&quot;ShowWhenNoData&quot;:true,&quot;IsEnabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;Icon&quot;:&quot;far fa-calendar-alt&quot;,&quot;Settings&quot;:{&quot;EventCssClasses&quot;:{&quot;ViewId&quot;:890,&quot;Id&quot;:1493,&quot;Name&quot;:&quot;EventCssClasses&quot;,&quot;ValueType&quot;:null,&quot;ValueToString&quot;:null,&quot;Value&quot;:null,&quot;LastModifiedBy&quot;:5,&quot;LastModifiedDate&quot;:&quot;2026-02-27T12:36:42.0777007+00:00&quot;,&quot;IsDeleted&quot;:false}},&quot;IsDeleted&quot;:false},{&quot;Definition&quot;:{&quot;Id&quot;:&quot;Cards&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Cards&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Renders data in as cards.&quot;},&quot;FaIcon&quot;:&quot;fas fa-th-large&quot;,&quot;TypeStr&quot;:&quot;PlantAnApp.Listing.ViewProviders.CardViewProvider, DnnSharp.ActionGrid.Core&quot;,&quot;Settings&quot;:{&quot;rendersTopButtons&quot;:false,&quot;rendersBottomButtons&quot;:true},&quot;Parameters&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;PageSizes&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Page Sizes&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Comma delimited list with page sizes that the user can select from.&quot;},&quot;Placeholder&quot;:null,&quot;DefaultValue&quot;:null,&quot;Default&quot;:&quot;10,20,50&quot;,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;DefaultPageSize&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Default Page Size&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;The default page size must be a number from the list with all page sizes.&quot;},&quot;Placeholder&quot;:null,&quot;DefaultValue&quot;:null,&quot;Default&quot;:10,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;CardCssClasses&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Card Css Classes&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;The custom Css classes for each item&quot;},&quot;Placeholder&quot;:null,&quot;DefaultValue&quot;:null,&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;SupportsExpressions&quot;:true},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]}]},&quot;Id&quot;:891,&quot;ListingModuleId&quot;:917,&quot;ViewName&quot;:&quot